diff --git a/src/router.js b/src/router.js
index a001e41..b4a7239 100644
--- a/src/router.js
+++ b/src/router.js
@@ -4,6 +4,12 @@
 export class Router {
   constructor() {
     this.routes = []
+    this.middlewares = []
+  }
+
+  use(fn) {
+    this.middlewares.push(fn)
+    return this
   }

   add(method, pattern, handler) {
@@ -39,4 +45,39 @@ export class Router {
     }
     return null
   }
+
+  async dispatch(ctx) {
+    // normalize ctx
+    ctx = ctx || {}
+    ctx.params = ctx.params || {}
+    ctx.state = ctx.state || {}
+    // determine path for routing
+    const match = this.match(ctx.method, ctx.path)
+
+    // run middleware chain first
+    const runMiddlewares = async (i) => {
+      if (i >= this.middlewares.length) return null
+      const mw = this.middlewares[i]
+      const res = await mw(ctx, () => runMiddlewares(i + 1))
+      return res
+    }
+
+    // execute middleware then handler
+    try {
+      const mwRes = await runMiddlewares(0)
+      if (mwRes) return mwRes
+      if (!match) {
+        return { status: 404, body: { error: 'Not found' } }
+      }
+      // fill in params for handler
+      ctx = { ...ctx, params: match.params }
+      const res = await match.handler(ctx)
+      return res
+    } catch (err) {
+      if (typeof err?.status === 'number') {
+        return { status: err.status, body: { error: err.message } }
+      }
+      return { status: 500, body: { error: 'Internal error' } }
+    }
+  }
 }
diff --git a/src/server.js b/src/server.js
index 0969320..9f09eac 100644
--- a/src/server.js
+++ b/src/server.js
@@ -11,6 +11,34 @@ import { formatCurrency } from './format.js'
 export function createApp(inventory = Inventory.fromFile()) {
   const router = new Router()

+  // Simple per-request API key based auth middleware and request-id
+  router.use(async (ctx, next) => {
+    // extract headers; ensure exists
+    ctx.headers = ctx.headers ?? {}
+    // API key auth if configured
+    const apiKeysRaw = process.env.API_KEYS
+    if (apiKeysRaw) {
+      const validKeys = apiKeysRaw.split(',').map((k) => k.trim()).filter(Boolean)
+      const method = ctx.method
+      const isMutating = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)
+      if (isMutating) {
+        const provided = (ctx.headers['x-api-key'] ?? '').trim()
+        if (!validKeys.includes(provided)) {
+          return { status: 401, body: { error: 'Unauthorized' } }
+        }
+      }
+    }
+    // request id generation
+    const id = `req_${Date.now()}_${Math.floor(Math.random() * 1e6)}`
+    ctx.state = ctx.state ?? {}
+    ctx.state.requestId = id
+    const res = await next()
+    // attach header after response is produced
+    if (res && !res.headers) res.headers = {}
+    res.headers = { ...(res?.headers ?? {}), 'x-request-id': id }
+    return res
+  })
+
   router.get('/health', () => ({ status: 200, body: { status: 'ok' } }))

   router.get('/books', () => ({ status: 200, body: inventory.list() }))
@@ -31,13 +59,16 @@ export function createApp(inventory = Inventory.fromFile()) {

   return async function handle(req) {
     const url = new URL(req.url, 'http://localhost')
-    const match = router.match(req.method, url.pathname)
-    if (!match) return { status: 404, body: { error: 'Not found' } }
-    try {
-      return await match.handler({ params: match.params, query: url.searchParams, body: req.body ?? {} })
-    } catch (err) {
-      return { status: 500, body: { error: err.message } }
+    const ctx = {
+      method: req.method,
+      path: url.pathname,
+      query: url.searchParams,
+      body: req.body ?? {},
+      headers: req.headers ?? {},
+      state: req.state ?? {},
     }
+    const out = await router.dispatch(ctx)
+    return out
   }
 }
